import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-postgres'

/**
 * Localize `Posts.slug`.
 *
 * Generated by `migrate:create`, then hand-edited to preserve data. The generated
 * version added the localized columns and dropped the originals in one statement
 * — which would have deleted every article slug on the site, and with them every
 * live Journal URL. The copy below sits between the two.
 *
 * The slug is copied into ALL EIGHT locales, not just `en`. Until now one slug
 * served every market, so `/de/journal/what-your-gut-is-telling-you` was a
 * working URL. Every query in the app sets `fallbackLocale: false` — deliberately,
 * so a missing translation is a 404 rather than a duplicate of the English page —
 * which means a slug present only in `en` would silently 404 the other seven
 * markets. Copying to all eight reproduces today's behaviour exactly and leaves
 * editors free to diverge per locale afterwards.
 *
 * Locales come from `enum_range` rather than a written-out list, so this stays
 * correct for whatever `_locales` actually holds at the time it runs.
 *
 * The index changes shape as well as table: it was UNIQUE on `posts.slug`, and a
 * unique index on a localized column enforces uniqueness across all locales at
 * once — it would reject a German slug because an unrelated Dutch post already
 * used that string. Per-locale uniqueness is enforced by the validate hook in
 * `fields/slug.ts` instead.
 */
export async function up({ db }: MigrateUpArgs): Promise<void> {
  // 1. Add the localized columns. The drops are deferred to step 4.
  await db.execute(sql`
    DROP INDEX "posts_slug_idx";
    DROP INDEX "_posts_v_version_version_slug_idx";
    ALTER TABLE "posts_locales" ADD COLUMN "slug" varchar;
    ALTER TABLE "_posts_v_locales" ADD COLUMN "version_slug" varchar;
    CREATE INDEX "posts_slug_idx" ON "posts_locales" USING btree ("slug","_locale");
    CREATE INDEX "_posts_v_version_version_slug_idx" ON "_posts_v_locales" USING btree ("version_slug","_locale");
  `)

  // 2. Copy every existing slug into every locale.
  //
  // Upsert on the (_locale, _parent_id) unique index: a locale row already
  // exists wherever the post has any other localized content, and does not where
  // it has none. `_locale` and `_parent_id` are the only columns that are NOT
  // NULL without a default, so this three-column insert is complete.
  await db.execute(sql`
    INSERT INTO "posts_locales" ("_locale", "_parent_id", "slug")
    SELECT locale.code, p."id", p."slug"
    FROM "posts" p
    CROSS JOIN (
      SELECT unnest(enum_range(NULL::"public"."_locales")) AS code
    ) AS locale
    WHERE p."slug" IS NOT NULL AND p."slug" <> ''
    ON CONFLICT ("_locale", "_parent_id") DO UPDATE
      SET "slug" = EXCLUDED."slug"
      WHERE "posts_locales"."slug" IS NULL;
  `)

  // 3. The same for version history, so drafts and restore-version keep working.
  // `_posts_v_locales._parent_id` points at `_posts_v.id` — the version row —
  // not at the post.
  await db.execute(sql`
    INSERT INTO "_posts_v_locales" ("_locale", "_parent_id", "version_slug")
    SELECT locale.code, v."id", v."version_slug"
    FROM "_posts_v" v
    CROSS JOIN (
      SELECT unnest(enum_range(NULL::"public"."_locales")) AS code
    ) AS locale
    WHERE v."version_slug" IS NOT NULL AND v."version_slug" <> ''
    ON CONFLICT ("_locale", "_parent_id") DO UPDATE
      SET "version_slug" = EXCLUDED."version_slug"
      WHERE "_posts_v_locales"."version_slug" IS NULL;
  `)

  // 4. Refuse to drop the source column if any post did not make it across.
  //
  // Without this the migration reports success and the damage only shows up as
  // 404s later, once the column it could have been recovered from is gone.
  await db.execute(sql`
    DO $$
    DECLARE
      missing integer;
    BEGIN
      SELECT count(*) INTO missing
      FROM "posts" p
      WHERE p."slug" IS NOT NULL AND p."slug" <> ''
        AND NOT EXISTS (
          SELECT 1 FROM "posts_locales" pl
          WHERE pl."_parent_id" = p."id" AND pl."slug" = p."slug"
        );

      IF missing > 0 THEN
        RAISE EXCEPTION
          'Aborting: % post(s) have no localized slug. Refusing to drop posts.slug.', missing;
      END IF;
    END $$;
  `)

  // 5. Now the originals can go.
  await db.execute(sql`
    ALTER TABLE "posts" DROP COLUMN "slug";
    ALTER TABLE "_posts_v" DROP COLUMN "version_slug";
  `)
}

/**
 * Rollback.
 *
 * Reordered from the generated version, which created the UNIQUE index on
 * `posts.slug` and dropped the localized column BEFORE anything could be copied
 * back. Here the column is added, filled from the locale rows, and only then
 * indexed — so if two locales diverged into slugs that collide as one unique
 * value, the failure is a clear constraint violation rather than a silently
 * empty column.
 *
 * Per-locale slugs other than the chosen one are lost, which is inherent to
 * un-localizing a field and not something this migration can avoid.
 */
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
    DROP INDEX "posts_slug_idx";
    DROP INDEX "_posts_v_version_version_slug_idx";
    ALTER TABLE "posts" ADD COLUMN "slug" varchar;
    ALTER TABLE "_posts_v" ADD COLUMN "version_slug" varchar;
  `)

  // English first, then any locale that has a value — a post translated only
  // into German should come back with its German slug rather than nothing.
  await db.execute(sql`
    UPDATE "posts" p
    SET "slug" = chosen."slug"
    FROM (
      SELECT DISTINCT ON (pl."_parent_id")
             pl."_parent_id", pl."slug"
      FROM "posts_locales" pl
      WHERE pl."slug" IS NOT NULL AND pl."slug" <> ''
      ORDER BY pl."_parent_id", (pl."_locale" = 'en') DESC, pl."_locale"
    ) AS chosen
    WHERE chosen."_parent_id" = p."id";
  `)

  await db.execute(sql`
    UPDATE "_posts_v" v
    SET "version_slug" = chosen."version_slug"
    FROM (
      SELECT DISTINCT ON (vl."_parent_id")
             vl."_parent_id", vl."version_slug"
      FROM "_posts_v_locales" vl
      WHERE vl."version_slug" IS NOT NULL AND vl."version_slug" <> ''
      ORDER BY vl."_parent_id", (vl."_locale" = 'en') DESC, vl."_locale"
    ) AS chosen
    WHERE chosen."_parent_id" = v."id";
  `)

  await db.execute(sql`
    ALTER TABLE "posts_locales" DROP COLUMN "slug";
    ALTER TABLE "_posts_v_locales" DROP COLUMN "version_slug";
    CREATE UNIQUE INDEX "posts_slug_idx" ON "posts" USING btree ("slug");
    CREATE INDEX "_posts_v_version_version_slug_idx" ON "_posts_v" USING btree ("version_slug");
  `)
}
